import base64
import os

def clean_and_decode_base64(b64_string, output_filename="output_preview.png"):
    try:
        # 1. 拔掉可能存在的 JSON 殘留符號 (例如：[" 或 "])
        b64_string = b64_string.strip('[]"\' ')
        
        # 2. 自動過濾網頁原檔前綴 (例如：data:image/jpeg;base64,)
        if "," in b64_string:
            b64_string = b64_string.split(",")[1]
            
        # 3. 處理網路傳輸可能漏掉的等號 (Padding)
        missing_padding = len(b64_string) % 4
        if missing_padding:
            b64_string += "=" * (4 - missing_padding)
            
        # 4. 開始解碼成二進位圖片資料
        image_bytes = base64.b64decode(b64_string)
        
        # 5. 實體寫入硬碟，生出圖片檔案
        with open(output_filename, "wb") as f:
            f.write(image_bytes)
            
        print(f"✨ 解碼成功！圖片已儲存至：{os.path.abspath(output_filename)}")
        return True
        
    except Exception as e:
        print(f"❌ 解碼失敗，原因: {e}")
        return False

